"""A minimal Flask REST API exposing a text transformation endpoint."""

from typing import Any, Callable, Dict, Tuple, Union

from flask import Flask, Response, jsonify, request

app = Flask(__name__)

# Map of supported operation names to the callable implementing them.
OPERATIONS: Dict[str, Callable[[str], Union[str, int]]] = {
    "uppercase": lambda text: text.upper(),
    "reverse": lambda text: text[::-1],
    "count_words": lambda text: len(text.split()),
}


def error_response(message: str, status: int = 400) -> Tuple[Response, int]:
    """Build a JSON error response with the given message and status code."""
    return jsonify({"error": message}), status


@app.route("/api/transform", methods=["POST"])
def transform() -> Tuple[Response, int]:
    """Apply a text transformation to the supplied text.

    Expects a JSON body of the form::

        {"text": "Hello World", "operation": "uppercase"}

    Supported operations are ``uppercase`` (upper-cased text), ``reverse``
    (character-reversed text) and ``count_words`` (whitespace-separated word
    count).

    Returns:
        A tuple of (Flask JSON response, HTTP status code). On success the
        response is HTTP 200 with ``result``, ``operation`` and
        ``original_length`` keys. On any validation failure the response is
        HTTP 400 with a single ``error`` key describing the problem.
    """
    payload: Any = request.get_json(silent=True)

    if payload is None:
        return error_response("Request body must be valid JSON.")

    if not isinstance(payload, dict):
        return error_response("Request body must be a JSON object.")

    if "text" not in payload:
        return error_response("Missing required field: 'text'.")

    text: Any = payload["text"]
    if not isinstance(text, str):
        return error_response("Field 'text' must be a string.")

    if "operation" not in payload:
        return error_response("Missing required field: 'operation'.")

    operation: Any = payload["operation"]
    supported = ", ".join(sorted(OPERATIONS))
    if not isinstance(operation, str) or operation not in OPERATIONS:
        return error_response(f"Field 'operation' must be one of: {supported}.")

    result: Union[str, int] = OPERATIONS[operation](text)

    return (
        jsonify(
            {
                "result": result,
                "operation": operation,
                "original_length": len(text),
            }
        ),
        200,
    )


if __name__ == "__main__":
    app.run(debug=True, port=5000)
```

Notes:
- `jsonify` sets `Content-Type: application/json` on both success and error responses automatically.
- `get_json(silent=True)` returns `None` for malformed bodies or a missing/incorrect content type, which is caught by the first check instead of raising a 415/400 HTML error page.
- Validation order is text-before-operation, so the error message points at the first problem found.
- `count_words` uses `str.split()` with no argument, which collapses runs of whitespace and ignores leading/trailing spaces.

Run with `pip install flask && python app.py`, then:

```bash
curl -X POST http://localhost:5000/api/transform \
  -H 'Content-Type: application/json' \
  -d '{"text": "Hello World", "operation": "reverse"}'
```

